import os
import json
import numpy as np
import sys

N = 26

sys.path.append('storage/noesis')
try:
    from compare_utils import read_active_pairs_csv, read_active_boundary_csv, jaccard
except Exception:
    read_active_pairs_csv = None
    read_active_boundary_csv = None
    jaccard = None

def load_saved_best():
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt')
        r = np.loadtxt('storage/noesis/latest_radii.txt')
        c = np.array(c, dtype=float).reshape(N, 2)
        r = np.array(r, dtype=float).reshape(N,)
        return c, r
    except Exception:
        return None, None

def grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = [[x, y] for x in coords for y in coords]
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    radii = [float(r0)] * 25 + [float(d - r0 - eps)]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)

def construct_packing():
    centers, radii = load_saved_best()
    if centers is None:
        centers, radii = grid_plus_hole_seed()

    results = {
        'status': 'ok',
        'note': 'Comparing active sets at tol=1e-8 if both lineages’ files are present.',
        'paths': {}
    }

    try:
        os.makedirs('storage/noesis/exports', exist_ok=True)
    except Exception:
        pass

    if read_active_pairs_csv is not None:
        # My files
        mine_pairs_path = 'storage/noesis/exports/active_pairs_tol1e8.csv'
        mine_bdry_path  = 'storage/noesis/exports/active_boundary_tol1e8.csv'
        # Aletheia’s files (read-only)
        their_pairs_path = 'storage/aletheia/active_pairs_tol1e8.csv'
        their_bdry_path  = 'storage/aletheia/active_boundary_tol1e8.csv'

        results['paths'] = {
            'mine_pairs': mine_pairs_path,
            'mine_boundary': mine_bdry_path,
            'their_pairs': their_pairs_path,
            'their_boundary': their_bdry_path,
        }

        mine_pairs = read_active_pairs_csv(mine_pairs_path)
        mine_bdry  = read_active_boundary_csv(mine_bdry_path)
        their_pairs = read_active_pairs_csv(their_pairs_path)
        their_bdry  = read_active_boundary_csv(their_bdry_path)

        comp = {}

        if mine_pairs is not None and their_pairs is not None:
            jc, inter, uni = jaccard(mine_pairs, their_pairs)
            comp['pairs'] = {
                'mine_count': len(mine_pairs),
                'their_count': len(their_pairs),
                'jaccard': jc,
                'intersection': inter,
                'union': uni
            }
        else:
            comp['pairs'] = {'available': False}

        if mine_bdry is not None and their_bdry is not None:
            jc_b, inter_b, uni_b = jaccard(mine_bdry, their_bdry)
            comp['boundary'] = {
                'mine_count': len(mine_bdry),
                'their_count': len(their_bdry),
                'jaccard': jc_b,
                'intersection': inter_b,
                'union': uni_b
            }
        else:
            comp['boundary'] = {'available': False}

        try:
            with open('storage/noesis/exports/jaccard_tol1e8.json', 'w') as f:
                json.dump({'results': results, 'comparison': comp}, f, indent=2)
        except Exception:
            pass

    return centers.astype(float), radii.astype(float)
